//! Strict bounded ASC CDL XML profile. Canonical semantic, not byte-for-byte XML roundtrip.
use serde::{Serialize,Deserialize};use roxmltree::Node;
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq)]pub struct Correction{pub id:String,pub slope:[f64;3],pub offset:[f64;3],pub power:[f64;3],pub saturation:f64,pub descriptions:Vec<String>,pub input_description:Option<String>,pub viewing_description:Option<String>,pub sop_descriptions:Vec<String>,pub sat_descriptions:Vec<String>}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq)]pub struct Collection{pub corrections:Vec<Correction>}
fn children<'a,'b>(n:Node<'a,'b>)->impl Iterator<Item=Node<'a,'b>>{n.children().filter(|n|n.is_element())}
fn valid_attrs(n:Node,allowed:&[&str])->Result<(),String>{for a in n.attributes(){if !allowed.contains(&a.name()){return Err(format!("unsupported XML attribute {}",a.name()))}}Ok(())}
fn text(n:Node)->Result<String,String>{valid_attrs(n,&[])?;if children(n).next().is_some(){return Err("nested text unsupported".into())}Ok(n.text().unwrap_or("").to_string())}
fn one<'a,'b>(n:Node<'a,'b>,name:&str)->Result<Node<'a,'b>,String>{let mut it=children(n).filter(|x|x.tag_name().name()==name);let x=it.next().ok_or(format!("missing {name}"))?;if it.next().is_some(){return Err(format!("duplicate {name}"))}Ok(x)}
fn nums(n:Node,count:usize)->Result<Vec<f64>,String>{let s=text(n)?;let a=s.split_whitespace().map(|s|s.parse::<f64>().map_err(|_|"invalid CDL number".to_string())).collect::<Result<Vec<_>,_>>()?;if a.len()!=count||a.iter().any(|x|!x.is_finite()||x.abs()>100.){return Err("CDL numeric count/range invalid".into())}Ok(a)}
fn parse_cc(n:Node)->Result<Correction,String>{valid_attrs(n,&["id"])?;let id=n.attribute("id").ok_or("ColorCorrection id required")?.to_string();if id.is_empty()||id.len()>1024{return Err("invalid CDL id".into())}for x in children(n){if !["SOPNode","SatNode","Description","InputDescription","ViewingDescription"].contains(&x.tag_name().name()){return Err(format!("unsupported ColorCorrection child {}",x.tag_name().name()))}}
 let sop=one(n,"SOPNode")?;let sat=one(n,"SatNode")?;valid_attrs(sop,&[])?;valid_attrs(sat,&[])?;
 for x in children(sop){valid_attrs(x,&[])?;if !["Slope","Offset","Power","Description"].contains(&x.tag_name().name()){return Err("unsupported SOPNode child".into())}}
 for x in children(sat){valid_attrs(x,&[])?;if !["Saturation","Description"].contains(&x.tag_name().name()){return Err("unsupported SatNode child".into())}}
 let triple=|k|->Result<[f64;3],String>{nums(one(sop,k)?,3)?.try_into().map_err(|_|"triple".into())};let descriptions=|p:Node|children(p).filter(|n|n.tag_name().name()=="Description").map(text).collect::<Result<Vec<_>,_>>();let opt=|k|->Result<Option<String>,String>{let count=children(n).filter(|x|x.tag_name().name()==k).count();if count>1{return Err(format!("duplicate{k}"))}if count==0{Ok(None)}else{Ok(Some(text(one(n,k)?)?))}};
 let c=Correction{id,slope:triple("Slope")?,offset:triple("Offset")?,power:triple("Power")?,saturation:nums(one(sat,"Saturation")?,1)?[0],descriptions:descriptions(n)?,input_description:opt("InputDescription")?,viewing_description:opt("ViewingDescription")?,sop_descriptions:descriptions(sop)?,sat_descriptions:descriptions(sat)?};c.validate()?;Ok(c)
}
impl Correction{pub fn validate(&self)->Result<(),String>{if self.slope.iter().any(|v|!v.is_finite()||*v<0.||*v>100.)||self.offset.iter().any(|v|!v.is_finite()||v.abs()>100.)||self.power.iter().any(|v|!v.is_finite()||*v<=0.||*v>100.)||!self.saturation.is_finite()||self.saturation<0.||self.saturation>100.{return Err("CDL slope/satnonnegative,powerpositive,bounded100".into())}Ok(())}}
impl Collection{
 pub fn parse(s:&str)->Result<Self,String>{if s.is_empty()||s.len()>1024*1024||s.contains("<!DOCTYPE")||s.contains("<!ENTITY"){return Err("CDL XML size1MiB/DTD/entity boundary".into())}let d=roxmltree::Document::parse(s).map_err(|e|e.to_string())?;let root=d.root_element();for n in d.descendants().filter(|n|n.is_element()){if ![None,Some("urn:ASC:CDL:v1.01"),Some("urn:ASC:CDL:v1.2")].contains(&n.tag_name().namespace()){return Err("unsupported CDL namespace".into())}if n!=root&&n.tag_name().namespace()!=root.tag_name().namespace(){return Err("mixedCDLnamespaces unsupported".into())}if n.children().filter(|x|x.is_text()).any(|x|!x.text().unwrap_or("").trim().is_empty())&&children(n).next().is_some(){return Err("mixed XML content unsupported".into())}}
 let corrections=match root.tag_name().name(){"ColorCorrection"=>vec![parse_cc(root)?],"ColorDecisionList"=>{valid_attrs(root,&[])?;let mut c=vec![];for decision in children(root){if decision.tag_name().name()!="ColorDecision"{return Err("unsupported CDL list child".into())}valid_attrs(decision,&[])?;if children(decision).count()!=1{return Err("ColorDecision requires one inline ColorCorrection".into())}c.push(parse_cc(one(decision,"ColorCorrection")?)?);if c.len()>1024{return Err("too many corrections".into())}}c},_=>return Err("root must be ColorCorrection or ColorDecisionList".into())};if corrections.is_empty(){return Err("empty CDL collection".into())}let mut ids=std::collections::HashSet::new();for c in &corrections{if !ids.insert(&c.id){return Err("duplicate CDL id".into())}}Ok(Self{corrections})}
 pub fn read(path:&str)->Result<Self,String>{use std::io::Read;if ![".cc",".cdl"].iter().any(|s|path.to_lowercase().ends_with(s)){return Err("requires.cc/.cdl".into())}let f=std::fs::File::open(path).map_err(|e|e.to_string())?;if !f.metadata().map_err(|e|e.to_string())?.is_file(){return Err("regular CDLfile required".into())}let mut s=String::new();f.take(1024*1024+1).read_to_string(&mut s).map_err(|e|e.to_string())?;Self::parse(&s)}
 pub fn select(&self,id:Option<&str>)->Result<&Correction,String>{match id{Some(id)=>self.corrections.iter().find(|x|x.id==id).ok_or("CDLid notfound".into()),None if self.corrections.len()==1=>Ok(&self.corrections[0]),_=>Err("multipleCDLs requireid".into())}}
 pub fn xml(&self,single:bool)->Result<String,String>{if single&&self.corrections.len()!=1{return Err(".cc needs onecorrection".into())}let esc=|s:&str|s.replace('&',"&amp;").replace('<',"&lt;").replace('>',"&gt;").replace('"',"&quot;").replace('\'',"&apos;");let mut out=String::from("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");if !single{out.push_str("<ColorDecisionList xmlns=\"urn:ASC:CDL:v1.2\">\n")}
 for c in &self.corrections{c.validate()?;if !single{out.push_str("<ColorDecision>\n")};out.push_str(&format!("<ColorCorrection id=\"{}\"{}>\n",esc(&c.id),if single{" xmlns=\"urn:ASC:CDL:v1.2\""}else{""}));for t in &c.descriptions{out.push_str(&format!("<Description>{}</Description>\n",esc(t)))}for(k,v)in[("InputDescription",&c.input_description),("ViewingDescription",&c.viewing_description)]{if let Some(v)=v{out.push_str(&format!("<{k}>{}</{k}>\n",esc(v)))}}
 out.push_str("<SOPNode>\n");for t in &c.sop_descriptions{out.push_str(&format!("<Description>{}</Description>\n",esc(t)))}for(k,v)in[("Slope",c.slope),("Offset",c.offset),("Power",c.power)]{out.push_str(&format!("<{k}>{} {} {}</{k}>\n",v[0],v[1],v[2]))}out.push_str("</SOPNode>\n<SatNode>\n");for t in &c.sat_descriptions{out.push_str(&format!("<Description>{}</Description>\n",esc(t)))}out.push_str(&format!("<Saturation>{}</Saturation>\n</SatNode>\n</ColorCorrection>\n",c.saturation));if !single{out.push_str("</ColorDecision>\n")}}if !single{out.push_str("</ColorDecisionList>\n")}Self::parse(&out)?;Ok(out)
 }
}
